'use strict';

/**
  * Транспорт для yandex-logger, позволяющий слать ошибки в error-booster.
  *
  * @param {TransportConfig} [config]
  * @returns {Function}
  */
const getTransport = config => {
    const socketType = config.socketType || 'unix_dgram';

    const isUnixDgramSocket = socketType === 'unix_dgram';
    const isHttpSocket = socketType === 'http';

    if (isUnixDgramSocket) {
        const { getTransport: getUnixDgramTransport } = require('./unix-dgram');
        return getUnixDgramTransport(config.socketPath);
    }

    if (isHttpSocket) {
        const { getTransport: getHttpTransport } = require('./http');
        return getHttpTransport({
            socketHost: config.socketHost,
            socketPort: config.socketPort,
            socketPath: config.socketPath,
            maxTotalSockets: config.maxTotalSockets,
        });
    }

    throw new TypeError('Unknown transport');
};

module.exports = {
    getTransport,
};

/**
  * @typedef {Object} TransportConfig
  * @property {String} [socketType] - Тип сокета ('http' или 'unix_dgram'), по умолчанию 'unix_dgram'
  * @property {String} [socketHost] - Хост сокета, по умолчанию 'localhost'
  * @property {Number} [socketPort] - Порт сокета, по умолчанию '12522'
  * @property {String} [socketPath] - Путь до сокета, по умолчанию '/errorbooster'
  * @property {Number} [maxTotalSockets] - Максимальное количество одновременных сокетов к unified agent,
                                            по умолчанию '8'
  */
